// Package assets embeds the repository's guides (docs/guides/*.md) and skills
// (skills/**). The staged copies under guides/ and skills/ are generated by
// `go generate` from their sources; the drift test fails when they differ.
package assets

//go:generate go run ./gen

import (
	"bufio"
	"bytes"
	"embed"
	"fmt"
	"io/fs"
	"path"
	"sort"
	"strings"

	"gopkg.in/yaml.v3"
)

//go:embed guides
var guidesFS embed.FS

//go:embed all:skills
var skillsFS embed.FS

// Topic is one guide: the file stem and its first `# ` heading.
type Topic struct {
	Name  string `json:"name"`
	Title string `json:"title"`
}

// Skill is one embedded skill: its directory name and SKILL.md description.
type Skill struct {
	Name        string `json:"name"`
	Description string `json:"description"`
}

// Topics lists every embedded guide, sorted by name.
func Topics() ([]Topic, error) {
	entries, err := guidesFS.ReadDir("guides")
	if err != nil {
		return nil, err
	}
	out := []Topic{}
	for _, e := range entries {
		name, ok := strings.CutSuffix(e.Name(), ".md")
		if e.IsDir() || !ok {
			continue
		}
		_, t, err := Guide(name)
		if err != nil {
			return nil, err
		}
		out = append(out, t)
	}
	return out, nil
}

// Guide returns the Markdown of the guide named topic and its Topic. The
// error wraps fs.ErrNotExist when there is no such guide.
func Guide(topic string) ([]byte, Topic, error) {
	if topic == "" || strings.ContainsAny(topic, `/\`) || strings.HasPrefix(topic, ".") {
		return nil, Topic{}, fmt.Errorf("guide %q: %w", topic, fs.ErrNotExist)
	}
	data, err := guidesFS.ReadFile("guides/" + topic + ".md")
	if err != nil {
		return nil, Topic{}, fmt.Errorf("guide %q: %w", topic, err)
	}
	title, err := firstHeading(data)
	if err != nil {
		return nil, Topic{}, fmt.Errorf("guide %q: %w", topic, err)
	}
	return data, Topic{Name: topic, Title: title}, nil
}

// firstHeading returns the text of the first line that starts with "# ".
func firstHeading(md []byte) (string, error) {
	sc := bufio.NewScanner(bytes.NewReader(md))
	sc.Buffer(make([]byte, 0, 64*1024), len(md)+1)
	for sc.Scan() {
		if title, ok := strings.CutPrefix(sc.Text(), "# "); ok {
			return strings.TrimSpace(title), nil
		}
	}
	return "", fmt.Errorf("no `# ` title line")
}

// SkillsFS returns the embedded skills tree, rooted at the skills directory:
// one directory per skill, each holding SKILL.md.
func SkillsFS() fs.FS {
	sub, err := fs.Sub(skillsFS, "skills")
	if err != nil {
		panic(err) // "skills" is a valid constant path
	}
	return sub
}

// Skills lists every embedded skill (a top-level directory with SKILL.md),
// sorted by name. Each SKILL.md must carry YAML frontmatter whose name equals
// the directory name and whose description is non-empty.
func Skills() ([]Skill, error) {
	root := SkillsFS()
	entries, err := fs.ReadDir(root, ".")
	if err != nil {
		return nil, err
	}
	out := []Skill{}
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		data, err := fs.ReadFile(root, path.Join(e.Name(), "SKILL.md"))
		if err != nil {
			return nil, fmt.Errorf("skill %q: %w", e.Name(), err)
		}
		s, err := parseSkill(data)
		if err != nil {
			return nil, fmt.Errorf("skill %q: %w", e.Name(), err)
		}
		if s.Name != e.Name() {
			return nil, fmt.Errorf("skill %q: frontmatter name %q differs from the directory name", e.Name(), s.Name)
		}
		out = append(out, s)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out, nil
}

// parseSkill reads the name and description from SKILL.md frontmatter.
func parseSkill(md []byte) (Skill, error) {
	text := strings.ReplaceAll(string(md), "\r\n", "\n")
	rest, ok := strings.CutPrefix(text, "---\n")
	if !ok {
		return Skill{}, fmt.Errorf("SKILL.md has no YAML frontmatter")
	}
	front, _, ok := strings.Cut(rest, "\n---")
	if !ok {
		return Skill{}, fmt.Errorf("SKILL.md frontmatter is not closed")
	}
	var meta struct {
		Name        string `yaml:"name"`
		Description string `yaml:"description"`
	}
	if err := yaml.Unmarshal([]byte(front), &meta); err != nil {
		return Skill{}, fmt.Errorf("SKILL.md frontmatter: %w", err)
	}
	desc := strings.TrimSpace(meta.Description)
	if meta.Name == "" || desc == "" {
		return Skill{}, fmt.Errorf("SKILL.md frontmatter needs name and description")
	}
	return Skill{Name: meta.Name, Description: desc}, nil
}
